// HasWorkspace applies the HasEdge predicate on the "workspace" edge.
func HasWorkspace() predicate.ConversationIntelligenceArtifact {
	return predicate.ConversationIntelligenceArtifact(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WorkspaceTable, WorkspaceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkspaceWith applies the HasEdge predicate on the "workspace" edge with a given conditions (other predicates).
func HasWorkspaceWith(preds ...predicate.RevenueWorkspace) predicate.ConversationIntelligenceArtifact {
	return predicate.ConversationIntelligenceArtifact(func(s *sql.Selector) {
		step := newWorkspaceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

